(() => {
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const state = { user:null, page:'dashboard', dashboard:null, profile:null, lessons:[], activeLesson:null, lab:'ohms-law', labHistory:[], skills:[], recommendations:[], classpulse:null, students:[], sort:null, sortTimer:null, authMode:'login', pendingPage:null, tutorHistory:[] };
const pageNames={dashboard:'Overview',learnbridge:'LearnBridge',studyshelf:'StudyShelf',classpulse:'Academic dashboard',skillpath:'SkillPath',labsim:'LabSim',campusaccess:'Accessibility',hub:'Learning Intelligence Hub',settings:'Settings',help:'Help & guidance'};
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateShort = s => { if(!s)return 'Just now'; const d=new Date(s.includes('T')?s:s.replace(' ','T')+'Z'); return isNaN(d)?s:d.toLocaleDateString(undefined,{month:'short',day:'numeric'}); };
const toast=(message,type='')=>{const el=document.createElement('div');el.className='toast '+type;el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),3800);};
async function api(url,opts={}){const options={credentials:'same-origin',...opts,headers:{...(opts.body?{'Content-Type':'application/json'}:{}),...(opts.headers||{})}};let res;try{res=await fetch(url,options)}catch(e){throw new Error('Network unavailable. Check your connection and try again.')}let data={};try{data=await res.json()}catch{}if(!res.ok){if(res.status===401&&state.user){state.user=null;showPublic();}throw new Error(data.error||`Request failed (${res.status}).`)}return data;}
const post=(url,body)=>api(url,{method:'POST',body:JSON.stringify(body)});const put=(url,body)=>api(url,{method:'PUT',body:JSON.stringify(body)});const patch=(url,body)=>api(url,{method:'PATCH',body:JSON.stringify(body)});
function setAuthMode(mode){state.authMode=mode;$$('.auth-tab').forEach(b=>b.classList.toggle('active',b.dataset.authMode===mode));$('#name-field').classList.toggle('hidden',mode!=='register');$('#auth-name').required=mode==='register';$('#auth-password').autocomplete=mode==='register'?'new-password':'current-password';$('#auth-title').textContent=mode==='register'?'Create a space that grows with you.':'Welcome to your learning space.';$('#auth-subtitle').textContent=mode==='register'?'Start with your goals. Shape the rest as you go.':'Sign in to continue your journey.';$('#auth-submit').innerHTML=(mode==='register'?'Create account':'Sign in')+' <span aria-hidden="true">↗</span>';$('#auth-error').textContent='';}
function openAuth(mode='login'){setAuthMode(mode);$('#auth-modal').classList.remove('hidden');setTimeout(()=>$(mode==='register'?'#auth-name':'#auth-email').focus(),50);}
function closeAuth(){$('#auth-modal').classList.add('hidden');}
function showPublic(){document.body.classList.remove('app-mode');$('#app-view').classList.add('hidden');$('#public-view').classList.remove('hidden');closeAuth();}
function showApp(user){state.user=user;$('#public-view').classList.add('hidden');$('#app-view').classList.remove('hidden');$('#user-name-mini').textContent=user.name;$('#user-name-top').textContent=user.name.split(' ')[0];$('#user-role-mini').textContent=user.role;$('#user-avatar').textContent=user.name.trim()[0]?.toUpperCase()||'L';$('#user-avatar-top').textContent=user.name.trim()[0]?.toUpperCase()||'L';$$('[data-staff-only]').forEach(n=>n.classList.toggle('hidden',!['admin','teacher'].includes(user.role)));closeAuth();const target=state.pendingPage||'dashboard';state.pendingPage=null;navigate(target);}
function setActiveNav(page){$$('.nav-item[data-page]').forEach(n=>n.classList.toggle('active',n.dataset.page===page));$('#breadcrumb-current').textContent=pageNames[page]||page;}
async function navigate(page){if(!state.user)return;state.page=page;setActiveNav(page);$('#sidebar').classList.remove('open');$('#sidebar-scrim').classList.add('hidden');$('#main').innerHTML='<div class="loading-state"><span class="spinner"></span><p>Preparing your learning space…</p></div>';try{switch(page){case'dashboard':await renderDashboard();break;case'learnbridge':await renderLearnBridge();break;case'studyshelf':await renderStudyShelf();break;case'classpulse':if(state.user.role==='admin')await renderClassPulse();else await renderStudentAcademic();break;case'skillpath':await renderSkillPath();break;case'labsim':await renderLabSim();break;case'campusaccess':await renderCampusAccess();break;case'hub':await renderHub();break;case'settings':await renderSettings();break;case'help':renderHelp();break;default:await renderDashboard();}}catch(e){$('#main').innerHTML=`<section class="surface"><div class="empty-state"><div class="empty-icon">!</div><strong>We couldn't load this view.</strong><p>${esc(e.message)}</p><button class="btn btn-primary" id="retry-page" style="margin-top:14px">Try again</button></div></section>`;$('#retry-page')?.addEventListener('click',()=>navigate(page));}$('#main').focus({preventScroll:true});}
function pageHeader(kicker,title,desc,actions=''){return `<div class="page-header"><div><div class="page-kicker">${esc(kicker)}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="page-header-actions">${actions}</div>`:''}</div>`;}
function surfaceTitle(title,desc='',action=''){return `<div class="surface-title"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function emptyState(title,desc,icon='✳'){return `<div class="empty-state"><div class="empty-icon">${icon}</div><strong>${title}</strong><p>${desc}</p></div>`;}
function progress(percent){return `<div class="progress-track" role="progressbar" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100" aria-label="${percent}% complete"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,percent))}%"></div></div>`;}
function recommendationCard(r){return `<article class="recommendation-card"><div class="rec-top"><span class="source-pill">${esc(r.source)}</span><span class="status-badge">${esc(r.status.replace('_',' '))}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.reason)}</p><p><strong>Next step:</strong> ${esc(r.action)}</p><div class="rec-actions">${r.status==='available'?`<button class="mini-btn primary" data-rec-action="accepted" data-id="${r.id}">Add to my plan</button>`:''}${r.status==='accepted'?`<button class="mini-btn primary" data-rec-action="in_progress" data-id="${r.id}">Start this</button>`:''}${r.status!=='completed'&&r.status!=='dismissed'?`<button class="mini-btn" data-rec-action="completed" data-id="${r.id}">Mark complete</button><button class="mini-btn" data-rec-action="dismissed" data-id="${r.id}">Dismiss</button>`:''}</div></article>`;}
function bindRecommendationActions(){ $$('[data-rec-action]').forEach(b=>b.addEventListener('click',async()=>{try{await patch(`/api/recommendations/${b.dataset.id}`,{status:b.dataset.recAction});toast('Recommendation updated.','success');await navigate(state.page);}catch(e){toast(e.message,'error')}})); }
async function renderDashboard(){const [d,p,l,h]=await Promise.all([api('/api/dashboard'),api('/api/profile'),api('/api/lessons'),api('/api/labs/history')]);state.dashboard=d;state.profile=p.profile;state.lessons=l.lessons;state.labHistory=h.attempts;state.recommendations=d.recommendations;const first=d.recommendations[0];const subjectNames=(p.profile.subjects||[]);const attempts=d.stats.quizAttempts;const labs=d.stats.labsCompleted;const avg=d.stats.quizAverage;const greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';$('#main').innerHTML=`<section class="dashboard-welcome"><div class="welcome-art"></div><div class="welcome-copy"><div class="welcome-overline">YOUR LEARNING JOURNEY · ${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase()}</div><h2>${greeting}, ${esc(state.user.name.split(' ')[0])}.</h2><p>Your next step doesn't need to be huge. Use what you've learned, notice what needs attention, and keep moving toward ${esc(p.profile.career_goal||'your goals')}.</p></div><button class="btn welcome-action" data-page="hub">Review my next step <span>↗</span></button></section>
<div class="stats-grid"><article class="stat-card"><div class="stat-head">Quiz attempts <span class="stat-icon stat-purple">◈</span></div><div class="stat-value">${attempts}</div><div class="stat-note">Completed assessments saved</div></article><article class="stat-card"><div class="stat-head">Quiz accuracy <span class="stat-icon stat-mint">↗</span></div><div class="stat-value">${attempts?avg+'%':'—'}</div><div class="stat-note">${attempts?'Average across recorded attempts':'Complete a quiz to begin'}</div></article><article class="stat-card"><div class="stat-head">Labs completed <span class="stat-icon stat-blue">⌘</span></div><div class="stat-value">${labs}</div><div class="stat-note">Practical activities recorded</div></article><article class="stat-card"><div class="stat-head">Skills tracked <span class="stat-icon stat-peach">✳</span></div><div class="stat-value">${d.stats.skillsTracked}</div><div class="stat-note">Declared or activity-supported</div></article></div>
<div class="content-grid"><section class="surface">${surfaceTitle('Your learning library','Pick up a topic or start something new',`<button class="link-button" data-page="learnbridge">All lessons ↗</button>`)}<div class="course-list">${l.lessons.map((x,i)=>`<article class="course-row"><span class="course-icon ${['stat-purple','stat-mint','stat-peach'][i]}">${['◈','⌁','∿'][i]}</span><div class="course-main"><strong>${esc(x.title)}</strong><small>${esc(x.subject)} · ${esc(x.duration)} · ${esc(x.level)}</small>${progress(attempts?Math.min(100,Math.round(avg+(i*4-4))):0)}</div><span class="course-percent">${attempts?Math.min(100,Math.max(0,Math.round(avg+(i*4-4))))+'%':'Start'}</span></article>`).join('')}</div></section><section class="surface">${surfaceTitle('Your next useful actions','Recommendations use your recorded activity',`<button class="link-button" data-page="hub">View all ↗</button>`)}${d.recommendations.length?d.recommendations.slice(0,2).map(recommendationCard).join(''):emptyState('Your plan starts here','Try a lesson or practical lab. Recommendations will appear when there is relevant activity to learn from.','✳')}</section></div>
<div class="content-grid"><section class="surface">${surfaceTitle('Recent activity','A record of meaningful learning actions')}${d.events.length?`<div class="activity-list">${d.events.map(e=>`<div class="activity-row"><span class="activity-dot">${e.module==='LabSim'?'⌘':e.module==='SkillPath'?'↗':e.module==='CampusAccess'?'◉':'◈'}</span><div class="activity-copy"><strong>${esc(e.event_type.replace(/[._]/g,' '))}</strong><small>${esc(e.module)}${e.metadata?.quiz?' · '+esc(e.metadata.quiz.replace(/-/g,' ')):''}${e.metadata?.score!=null?' · '+e.metadata.score+'/'+e.metadata.total:''}</small></div><span class="activity-time">${dateShort(e.created_at)}</span></div>`).join('')}</div>`:emptyState('Your learning story starts here','Complete a quiz, adjust a preference, or save a lab experiment to record your first activity.','↗')}</section><section class="surface">${surfaceTitle('Your focus','Based on your saved learning profile')}<div class="recommendation-card"><div class="rec-top"><span class="source-pill">CURRENT GOAL</span></div><h3>${esc(p.profile.goals||'Build consistent learning habits')}</h3><p>Career direction: <strong>${esc(p.profile.career_goal||'Not selected yet')}</strong></p><p>Focus subjects: ${subjectNames.length?subjectNames.map(esc).join(' · '):'Add subjects in Settings'}.</p><div class="rec-actions"><button class="mini-btn primary" data-page="settings">Update my profile</button><button class="mini-btn" data-page="skillpath">Explore careers</button></div></div><div class="inline-note">Progress indicators describe recorded activity—not intelligence, potential, or a guarantee of future outcomes.</div></section></div>
<section class="surface">${surfaceTitle('One ecosystem, right at hand','Move between connected learning tools')}</section><div class="module-shortcuts" style="margin-top:11px"><button class="shortcut" data-page="learnbridge"><span>◈</span><strong>LearnBridge</strong><small>Lessons & quizzes</small></button><button class="shortcut" data-page="skillpath"><span>↗</span><strong>SkillPath</strong><small>Skills & roadmap</small></button><button class="shortcut" data-page="labsim"><span>⌘</span><strong>LabSim</strong><small>Interactive practicals</small></button><button class="shortcut" data-page="campusaccess"><span>◉</span><strong>CampusAccess</strong><small>Reading preferences</small></button><button class="shortcut" data-page="hub"><span>✳</span><strong>Intelligence Hub</strong><small>Plan & recommendations</small></button></div>`;bindPageButtons();bindRecommendationActions();}
async function renderLearnBridge(){const [data,hist]=await Promise.all([api('/api/lessons'),api('/api/quizzes/history')]);state.lessons=data.lessons;const lesson=state.activeLesson?await api(`/api/lessons/${state.activeLesson}`).then(x=>x.lesson).catch(()=>null):null;const history=hist.attempts;$('#main').innerHTML=pageHeader('MODULE 01 · ADAPTIVE LEARNING','LearnBridge','Learn something clearly, practice it, and use your results to choose a useful next step.',`<button class="btn btn-primary" id="ask-tutor-open">Ask the learning assistant <span>✦</span></button>`)+ (lesson?renderLesson(lesson):`<div class="module-banner"><div class="page-kicker">LEARN → PRACTICE → REVIEW</div><h2>Small, focused sessions make progress visible.</h2><p>Each lesson includes a short explanation, an example, and a scored knowledge check. Quiz results are saved to your account and can shape future recommendations.</p></div>${history.length?(()=>{const groups={};history.forEach(a=>{const k=a.quiz_key;groups[k]??=[];groups[k].push(a.score/a.total*100)});const rows=Object.entries(groups).map(([k,v])=>({name:k.replace(/-/g,' '),avg:Math.round(v.reduce((a,b)=>a+b,0)/v.length),n:v.length}));const strong=rows.filter(x=>x.avg>=75),focus=rows.filter(x=>x.avg<70);return `<div class="content-grid equal" style="margin:16px 0"><section class="surface">${surfaceTitle('Evidence-backed strengths','Topics with 75%+ average on recorded quizzes')}${strong.length?strong.map(x=>`<div class="activity-row"><span class="activity-dot">✓</span><div class="activity-copy"><strong>${esc(x.name)}</strong><small>${x.avg}% average · ${x.n} attempt(s)</small></div></div>`).join(''):emptyState('Strengths are still emerging','Complete more knowledge checks. A high score is treated as evidence for this quiz topic only.','◈')}</section><section class="surface">${surfaceTitle('Topics to strengthen','Topics below 70% average on recorded quizzes')}${focus.length?focus.map(x=>`<div class="activity-row"><span class="activity-dot">↗</span><div class="activity-copy"><strong>${esc(x.name)}</strong><small>${x.avg}% average · revisit lesson and retry</small></div></div>`).join(''):emptyState('No clear review gap from current quizzes','If a topic feels difficult, ask the conversational assistant or take another check.','✦')}</section></div>`})():`<div class="inline-note" style="margin:16px 0">Your strengths and review areas will appear after you complete knowledge checks. The system uses quiz evidence—not assumptions about your ability.</div>`}<div class="lesson-grid">${data.lessons.map((l,i)=>`<article class="lesson-card"><span class="lesson-tag">${esc(l.tag)} · ${esc(l.level)}</span><h3>${esc(l.title)}</h3><p>${esc(l.summary)}</p><div class="lesson-meta"><span>${esc(l.subject)}</span><span>${esc(l.duration)}</span></div><button class="btn btn-primary" data-lesson="${l.id}">Open lesson <span>↗</span></button></article>`).join('')}</div><section class="surface" style="margin-top:17px">${surfaceTitle('Your assessment history','Calculated scores from submitted quizzes')}${history.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Quiz</th><th>Result</th><th>Accuracy</th><th>Date</th></tr></thead><tbody>${history.map(a=>`<tr><td>${esc(a.quiz_key.replace(/-/g,' '))}</td><td>${a.score}/${a.total}</td><td>${Math.round(a.score/a.total*100)}%</td><td>${dateShort(a.created_at)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No quizzes yet','Complete a lesson check to start building a record of demonstrated understanding.','◈')}</section>`);$$('[data-lesson]').forEach(b=>b.addEventListener('click',()=>{state.activeLesson=b.dataset.lesson;navigate('learnbridge')}));$('#ask-tutor-open')?.addEventListener('click',renderTutor);bindPageButtons();}
function renderLesson(l){return `<button class="mini-btn" id="back-lessons">← All lessons</button><div class="content-grid" style="margin-top:14px"><article class="surface"><div class="page-kicker">${esc(l.subject)} · ${esc(l.level)} · ${esc(l.duration)}</div><h2 style="font:800 23px Manrope,sans-serif;letter-spacing:-.8px;margin:12px 0">${esc(l.title)}</h2><div class="lesson-content"><p>${esc(l.content)}</p><h2>Worked example</h2><pre class="code-block">${esc(l.example)}</pre><p>As you work, ask yourself what each step means and why it is useful. Understanding the reason is more important than memorizing the final line.</p></div><div class="inline-note">Your quiz result is an educational indicator based on these questions—not a complete measure of mastery.</div><button class="btn btn-primary" id="start-quiz">Take the knowledge check <span>↗</span></button></article><aside class="surface">${surfaceTitle('What you will practice')}<div class="activity-list"><div class="activity-row"><span class="activity-dot">01</span><div class="activity-copy"><strong>Understand the core idea</strong><small>Explain it in your own words.</small></div></div><div class="activity-row"><span class="activity-dot">02</span><div class="activity-copy"><strong>Apply it to an example</strong><small>Notice the inputs and outcome.</small></div></div><div class="activity-row"><span class="activity-dot">03</span><div class="activity-copy"><strong>Check your understanding</strong><small>${l.questions.length} questions · instant feedback</small></div></div></div><div class="inline-note">Scores and recommendations are stored in your private learning account.</div></aside></div><div id="quiz-area"></div>`;}
$('#main').addEventListener('click',e=>{if(e.target.closest('#back-lessons')){state.activeLesson=null;navigate('learnbridge')}if(e.target.closest('#start-quiz'))startQuiz();});
function startQuiz(){const area=$('#quiz-area');if(!area||!state.activeLesson)return;const lessonKey=state.activeLesson;api(`/api/lessons/${lessonKey}`).then(({lesson:l})=>{area.innerHTML=`<section class="surface" style="margin-top:16px"><div class="page-kicker">KNOWLEDGE CHECK</div><h2 style="font:800 19px Manrope,sans-serif">${esc(l.title)} quiz</h2><p class="helper-text">Choose one answer for each question. Your score is calculated from the validated answer key and saved after submission.</p><form id="quiz-form">${l.questions.map((q,i)=>`<div class="quiz-question"><h3>${i+1}. ${esc(q.q)}</h3><div class="option-list">${q.opts.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" required><span>${esc(o)}</span></label>`).join('')}</div></div>`).join('')}<button class="btn btn-primary btn-large" type="submit" style="margin-top:17px">Submit answers <span>↗</span></button></form><div id="quiz-result"></div></section>`;$('#quiz-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const answers=l.questions.map((q,i)=>Number(new FormData(e.target).get('q'+i)));const r=await post(`/api/quizzes/${l.quiz}/submit`,{answers});$('#quiz-result').innerHTML=`<div class="quiz-result"><h3>${r.score}/${r.total} correct · ${r.percent}%</h3><p>Your attempt was saved. Use the feedback to choose what to review next.</p>${r.feedback.map((f,i)=>`<div class="feedback-item"><strong>${f.correct?'✓ Correct':'↻ Review'} — ${esc(f.correctAnswer)}</strong><br>${esc(f.explanation)}</div>`).join('')}</div>`;btn.remove();toast('Quiz result saved.','success');}catch(err){toast(err.message,'error');btn.disabled=false;}});area.scrollIntoView({behavior:document.body.classList.contains('reduce-motion')?'auto':'smooth',block:'start'});}).catch(e=>toast(e.message,'error'));}
async function renderTutor(){const existing=$('#tutor-modal');if(existing)existing.remove();state.tutorHistory=[];const wrap=document.createElement('div');wrap.id='tutor-modal';wrap.className='modal-backdrop';wrap.innerHTML=`<section class="auth-card tutor-card" role="dialog" aria-modal="true" aria-labelledby="tutor-title"><button class="modal-close" id="tutor-close" aria-label="Close dialog">×</button><div class="auth-brand"><span class="brand-mark">✦</span><span>LEARNBRIDGE · CONVERSATIONAL STUDY COACH</span></div><h2 id="tutor-title">Let's work it out together.</h2><p class="auth-intro">Ask follow-up questions naturally. The assistant keeps the recent conversation in context and uses your own learning evidence where available.</p><div id="tutor-thread" class="chat-thread" aria-live="polite"><div class="chat-message assistant">Hi ${esc(state.user.name.split(' ')[0])}! What subject or concept are you working on? Tell me what you understand so far, and we’ll take it one step at a time.</div></div><form id="tutor-form"><div class="form-field"><label for="tutor-prompt">Your message</label><textarea id="tutor-prompt" class="field-control" rows="3" required maxlength="1200" placeholder="Ask a question, say what confused you, or ask for another example…"></textarea></div><button class="btn btn-primary btn-block" type="submit">Send message ↗</button></form><div id="tutor-mode-note" class="chat-meta">Responses are labeled as live AI or fallback guidance.</div></section>`;document.body.append(wrap);$('#tutor-close').onclick=()=>wrap.remove();wrap.addEventListener('click',e=>{if(e.target===wrap)wrap.remove()});$('#tutor-form').onsubmit=async e=>{e.preventDefault();const input=$('#tutor-prompt'),btn=e.submitter,prompt=input.value.trim();if(!prompt)return;state.tutorHistory.push({role:'user',content:prompt});$('#tutor-thread').insertAdjacentHTML('beforeend',`<div class="chat-message user">${esc(prompt)}</div>`);input.value='';btn.disabled=true;btn.textContent='Thinking…';try{const r=await post('/api/assistant',{prompt,history:state.tutorHistory.slice(0,-1)});state.tutorHistory.push({role:'assistant',content:r.text});$('#tutor-thread').insertAdjacentHTML('beforeend',`<div class="chat-message assistant">${esc(r.text)}</div>`);$('#tutor-mode-note').textContent=(r.mode==='live-ai'?'Live AI response': 'Local fallback guidance — not a live AI response')+(r.note?' · '+r.note:'');$('#tutor-thread').scrollTop=$('#tutor-thread').scrollHeight;}catch(err){state.tutorHistory.pop();$('#tutor-thread').insertAdjacentHTML('beforeend',`<div class="chat-message assistant">I couldn’t send that message: ${esc(err.message)} Please try again.</div>`);}finally{btn.disabled=false;btn.innerHTML='Send message ↗';input.focus();}};}
async function renderLabSim(){const hist=await api('/api/labs/history');state.labHistory=hist.attempts;const labs=[{id:'ohms-law',name:"Ohm’s Law",desc:'Change voltage and resistance; see the ideal current update instantly.'},{id:'sorting-visualizer',name:'Sorting visualizer',desc:'Step through a real sorting algorithm and compare its operation count.'},{id:'sql-playground',name:'SQL practice',desc:'Run a constrained subset of SELECT queries against a local read-only practice dataset.'},{id:'chemistry-ph',name:'Chemistry · pH lab',desc:'Explore how hydrogen-ion concentration relates to pH in a simplified aqueous solution model.'},{id:'projectile-motion',name:'Physics · projectile motion',desc:'Change launch speed and angle and calculate idealized range and flight time.'},{id:'binary-search',name:'Binary search lab',desc:'Explore divide-and-conquer search and count comparisons.'},{id:'logic-gates',name:'Digital logic lab',desc:'Experiment with AND, OR, XOR, NAND, and NOR truth tables.'},{id:'statistics-lab',name:'Statistics lab',desc:'Calculate mean, median, range, and standard deviation from custom data.'},{id:'matrix-lab',name:'Matrix lab',desc:'Multiply two 2×2 matrices and inspect the result cells.'}];$('#main').innerHTML=pageHeader('MODULE 04 · PRACTICAL LEARNING','LabSim','Experiment safely, change inputs, observe results, and record what you learned.')+`<div class="module-banner"><div class="page-kicker">LEARN BY DOING</div><h2>Nine interactive labs. Real calculations and clearly stated models.</h2><p>Explore physics, chemistry, programming, SQL, digital logic, statistics, and matrices. Simulations run locally; saved attempts are attached to your account.</p></div><div class="lab-tabs">${labs.map(l=>`<button class="lab-tab ${state.lab===l.id?'active':''}" data-lab="${l.id}">${esc(l.name)}</button>`).join('')}</div><div id="lab-body"></div><section class="surface" style="margin-top:16px">${surfaceTitle('Your practical history','Saved experiment attempts')}${hist.attempts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Experiment</th><th>Recorded result</th><th>Completed</th><th>Date</th></tr></thead><tbody>${hist.attempts.map(a=>`<tr><td>${esc(a.lab_key.replace(/-/g,' '))}</td><td>${esc(JSON.stringify(a.result).slice(0,100))}</td><td>${a.completed?'Yes':'No'}</td><td>${dateShort(a.created_at)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No saved experiments yet','Change a parameter or run a practice task, then save your result.','⌘')}</section>`;$$('[data-lab]').forEach(b=>b.onclick=()=>{state.lab=b.dataset.lab;$$('[data-lab]').forEach(x=>x.classList.toggle('active',x===b));renderLabBody()});renderLabBody();}
function renderLabBody(){const body=$('#lab-body');if(!body)return;if(state.lab==='ohms-law'){body.innerHTML=`<div class="lab-workspace"><section class="surface">${surfaceTitle('Circuit simulator','Idealized DC circuit · Ohm’s Law')}<div class="lab-canvas"><svg class="circuit-svg" viewBox="0 0 340 145" role="img" aria-label="Simple circuit diagram with voltage source and resistor"><path d="M64 30 H125 M185 30 H280 V112 H64 V30" fill="none" stroke="#7c70df" stroke-width="3" stroke-linejoin="round"/><path d="M125 30 l8 -10 10 20 10 -20 10 20 10 -20 12 10" fill="none" stroke="#ef9f89" stroke-width="3" stroke-linejoin="round"/><circle cx="64" cy="71" r="20" fill="#e7e2ff" stroke="#7c70df" stroke-width="2"/><path d="M55 71h18 M64 62v18" stroke="#7c70df" stroke-width="2"/><text x="64" y="105" text-anchor="middle" font-size="10" fill="#77758d">Voltage</text><text x="155" y="15" text-anchor="middle" font-size="10" fill="#77758d">Resistance</text><path d="M217 105h36" stroke="#5ca98b" stroke-width="2"/><path d="m246 99 8 6-8 6" fill="none" stroke="#5ca98b" stroke-width="2"/><text x="235" y="128" text-anchor="middle" font-size="10" fill="#77758d">Current →</text></svg><div class="lab-value" id="current-value">2.00 <small>A current</small></div><p class="helper-text" id="ohm-explain">At 12 V and 6 Ω, current is 2 A.</p></div></section><section class="surface">${surfaceTitle('Adjust the circuit','Results update as values change')}<div class="lab-controls"><div class="range-row"><label for="voltage-range">Voltage <output id="voltage-output">12 V</output></label><input id="voltage-range" type="range" min="1" max="24" step="1" value="12"></div><div class="range-row"><label for="resistance-range">Resistance <output id="resistance-output">6 Ω</output></label><input id="resistance-range" type="range" min="1" max="24" step="1" value="6"></div><div class="inline-note">Formula: I = V ÷ R. This is an idealized educational model; real components may behave differently.</div><button class="btn btn-primary" id="save-ohm">Save this experiment <span>↗</span></button></div></section></div>`;const update=()=>{const v=Number($('#voltage-range').value),r=Number($('#resistance-range').value),i=v/r;$('#voltage-output').textContent=v+' V';$('#resistance-output').textContent=r+' Ω';$('#current-value').innerHTML=i.toFixed(2)+' <small>A current</small>';$('#ohm-explain').textContent=`At ${v} V and ${r} Ω, current is ${i.toFixed(2)} A.`;};$('#voltage-range').oninput=update;$('#resistance-range').oninput=update;$('#save-ohm').onclick=async()=>{try{const result={voltage:Number($('#voltage-range').value),resistance:Number($('#resistance-range').value),current:Number((Number($('#voltage-range').value)/Number($('#resistance-range').value)).toFixed(4)),formula:'I=V/R'};await post('/api/labs/ohms-law/complete',{result});toast('Experiment saved.','success');await renderLabSim();}catch(e){toast(e.message,'error')}};
 } else if(state.lab==='sorting-visualizer'){body.innerHTML=`<div class="lab-workspace"><section class="surface">${surfaceTitle('Sorting workspace','Values are sorted by the selected algorithm')}<div class="lab-canvas"><div class="sort-bars" id="sort-bars" role="img" aria-label="Sorting algorithm bar visualization"></div><div id="sort-status" class="helper-text">Ready to sort.</div></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:15px"><button class="btn btn-primary" id="sort-step">Next step</button><button class="btn btn-quiet" id="sort-run">Run to completion</button><button class="btn btn-quiet" id="sort-reset">Reset</button></div></section><section class="surface">${surfaceTitle('Experiment controls','Try a different input or algorithm')}<div class="form-field"><label for="sort-algorithm">Algorithm</label><select class="field-control" id="sort-algorithm"><option value="bubble">Bubble sort</option><option value="selection">Selection sort</option><option value="insertion">Insertion sort</option></select></div><div class="form-field"><label for="sort-values">Custom values (comma separated, max 12)</label><input class="field-control" id="sort-values" value="8, 3, 6, 1, 9, 4, 2"></div><button class="btn btn-quiet" id="sort-load">Load values</button><div class="inline-note" id="sort-explain">Each step is a real comparison or swap from the selected algorithm. Operation counts describe this run, not a benchmark.</div><button class="btn btn-primary" id="save-sort">Save completed lab</button></section></div>`;initSort();
 }else if(state.lab==='chemistry-ph'){body.innerHTML=`<div class="lab-workspace"><section class="surface">${surfaceTitle('pH explorer','Idealized aqueous solution model')}<div class="lab-canvas"><div class="lab-value" id="ph-value">pH 7.00</div><div id="ph-class" class="source-pill">Neutral</div><p id="ph-explain" class="helper-text">At pH 7, the solution is neutral in this simplified model.</p><div style="height:12px;width:100%;border-radius:99px;background:linear-gradient(90deg,#df6d5d,#efc85c,#65b887,#5d91df);margin-top:10px"></div><div style="display:flex;justify-content:space-between;width:100%;font-size:9px;color:var(--muted)"><span>Acidic · 0</span><span>Neutral · 7</span><span>Basic · 14</span></div></div></section><section class="surface">${surfaceTitle('Change the pH','A conceptual model; no real chemicals are used')}<div class="range-row"><label for="ph-range">pH value <output id="ph-output">7.0</output></label><input id="ph-range" type="range" min="0" max="14" step="0.5" value="7" style="width:100%;accent-color:#7868ed"></div><div class="inline-note">pH = −log₁₀[H⁺]. Each one-unit decrease in pH corresponds to a tenfold increase in hydrogen-ion concentration. This teaching model does not replace laboratory measurement.</div><button class="btn btn-primary" id="save-ph">Save chemistry experiment ↗</button></section></div>`;const update=()=>{const ph=Number($('#ph-range').value);$('#ph-output').textContent=ph.toFixed(1);$('#ph-value').textContent='pH '+ph.toFixed(1);$('#ph-class').textContent=ph<7?'Acidic':ph>7?'Basic':'Neutral';$('#ph-explain').textContent=ph<7?`pH ${ph.toFixed(1)} is acidic in this model; lower pH means higher hydrogen-ion concentration.`:ph>7?`pH ${ph.toFixed(1)} is basic in this model; higher pH means lower hydrogen-ion concentration than neutral water.`:'pH 7 is neutral in this simplified model at the reference conditions.';};$('#ph-range').oninput=update;$('#save-ph').onclick=async()=>{try{await post('/api/labs/chemistry-ph/complete',{result:{pH:Number($('#ph-range').value),classification:$('#ph-range').value<7?'acidic':$('#ph-range').value>7?'basic':'neutral',model:'idealized educational pH scale'}});toast('Chemistry experiment saved.','success');await renderLabSim();}catch(e){toast(e.message,'error')}};update();}else if(state.lab==='projectile-motion'){body.innerHTML=`<div class="lab-workspace"><section class="surface">${surfaceTitle('Projectile motion','Idealized no-air-resistance model')}<div class="lab-canvas"><svg viewBox="0 0 340 160" style="width:100%;max-width:400px" role="img" aria-label="Illustrative projectile trajectory"><path d="M20 130H320 M25 135V15" stroke="var(--line)" stroke-width="2" fill="none"/><path id="trajectory-path" d="M25 130 Q170 -5 315 130" stroke="#7868ed" stroke-width="3" fill="none"/><circle id="projectile-dot" cx="170" cy="63" r="6" fill="#ef9f89"/></svg><div class="lab-value" id="range-value">Range: 40.8 m</div><p class="helper-text" id="flight-value">Flight time: 2.04 s</p></div></section><section class="surface">${surfaceTitle('Set launch conditions','Assumes level ground and gravitational acceleration 9.81 m/s²')}<div class="range-row"><label for="speed-range">Launch speed <output id="speed-output">20 m/s</output></label><input id="speed-range" type="range" min="5" max="40" step="1" value="20" style="width:100%;accent-color:#7868ed"></div><div class="range-row" style="margin-top:18px"><label for="angle-range">Launch angle <output id="angle-output">45°</output></label><input id="angle-range" type="range" min="10" max="80" step="1" value="45" style="width:100%;accent-color:#7868ed"></div><div class="inline-note">Range = v² sin(2θ) / g. Flight time = 2v sin(θ) / g. Real trajectories vary with air resistance, launch height, and local conditions.</div><button class="btn btn-primary" id="save-projectile">Save physics experiment ↗</button></section></div>`;const update=()=>{const v=Number($('#speed-range').value),deg=Number($('#angle-range').value),a=deg*Math.PI/180,g=9.81,range=v*v*Math.sin(2*a)/g,time=2*v*Math.sin(a)/g,height=v*v*Math.sin(a)**2/(2*g);$('#speed-output').textContent=v+' m/s';$('#angle-output').textContent=deg+'°';$('#range-value').textContent='Range: '+range.toFixed(2)+' m';$('#flight-value').textContent='Flight time: '+time.toFixed(2)+' s · peak height: '+height.toFixed(2)+' m';const x=25+Math.min(285,range/180*285),y=130-Math.min(100,height/80*100);$('#projectile-dot').setAttribute('cx',Math.min(315,x));$('#projectile-dot').setAttribute('cy',Math.max(20,y));$('#trajectory-path').setAttribute('d',`M25 130 Q${Math.min(170,25+range/2)} ${Math.max(15,130-Math.min(110,height/80*220))} ${Math.min(315,x)} 130`);};$('#speed-range').oninput=update;$('#angle-range').oninput=update;$('#save-projectile').onclick=async()=>{try{const v=Number($('#speed-range').value),deg=Number($('#angle-range').value),a=deg*Math.PI/180;await post('/api/labs/projectile-motion/complete',{result:{speed:v,angleDegrees:deg,rangeMeters:Number((v*v*Math.sin(2*a)/9.81).toFixed(3)),flightTimeSeconds:Number((2*v*Math.sin(a)/9.81).toFixed(3)),model:'idealized no-air-resistance'}});toast('Physics experiment saved.','success');await renderLabSim();}catch(e){toast(e.message,'error')}};update();}else{body.innerHTML=`<div class="lab-workspace"><section class="surface">${surfaceTitle('SQL query editor','Read-only sample database')}<div class="form-field"><label for="sql-query">Your query</label><textarea class="field-control" id="sql-query" rows="5">SELECT name, score FROM assessments WHERE score >= 80 ORDER BY score DESC;</textarea></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-primary" id="sql-run">Run query</button><button class="btn btn-quiet" id="sql-example">Load JOIN example</button></div><div id="sql-result" style="margin-top:17px"></div></section><section class="surface">${surfaceTitle('Available tables','Sample data only')}<div class="activity-list"><div class="activity-row"><span class="activity-dot">▦</span><div class="activity-copy"><strong>students</strong><small>id · name · course</small></div></div><div class="activity-row"><span class="activity-dot">▦</span><div class="activity-copy"><strong>courses</strong><small>id · title · subject</small></div></div><div class="activity-row"><span class="activity-dot">▦</span><div class="activity-copy"><strong>assessments</strong><small>student_id · course_id · score</small></div></div></div><div class="inline-note">Supported: SELECT, WHERE comparisons, ORDER BY, LIMIT, and a guided INNER JOIN pattern. This is a constrained teaching parser, not a general-purpose SQL server. Writes and arbitrary SQL execution are disabled.</div><button class="btn btn-primary" id="save-sql">Save SQL practice</button></section></div>`;initSQL();}}
function initSort(){const valuesInput=$('#sort-values'),algorithm=$('#sort-algorithm');let values=[8,3,6,1,9,4,2];let steps=[],idx=0,ops=0,done=false;function makeSteps(){steps=[];ops=0;done=false;const a=[...values];const add=(type,i,j,arr,note)=>steps.push({type,i,j,arr:[...arr],note,ops:steps.length+1});if(algorithm.value==='bubble'){for(let end=a.length-1;end>0;end--)for(let i=0;i<end;i++){add('compare',i,i+1,a,`Compare ${a[i]} and ${a[i+1]}.`);if(a[i]>a[i+1]){[a[i],a[i+1]]=[a[i+1],a[i]];add('swap',i,i+1,a,`Swap them so the smaller value moves left.`);}}}else if(algorithm.value==='selection'){for(let i=0;i<a.length-1;i++){let m=i;for(let j=i+1;j<a.length;j++){add('compare',m,j,a,`Compare candidate ${a[m]} with ${a[j]}.`);if(a[j]<a[m])m=j;}if(m!==i){[a[i],a[m]]=[a[m],a[i]];add('swap',i,m,a,`Place the smallest remaining value at position ${i}.`);}}}else{for(let i=1;i<a.length;i++){let j=i;while(j>0){add('compare',j-1,j,a,`Compare adjacent values ${a[j-1]} and ${a[j]}.`);if(a[j-1]<=a[j])break;[a[j-1],a[j]]=[a[j],a[j-1]];add('swap',j-1,j,a,'Move the smaller value one position left.');j--;}}}steps.push({type:'done',arr:[...a],note:`Finished. ${ops} recorded operations in this run.`,ops:steps.length});idx=0;draw();}function draw(){const step=steps[Math.min(idx,steps.length-1)];if(!step)return;ops=idx;$('#sort-bars').innerHTML=step.arr.map((v,i)=>`<div class="sort-bar" style="height:${Math.max(12,v*13)}px;${(step.i===i||step.j===i)&&step.type!=='done'?'background:linear-gradient(180deg,#ffb69e,#e88976)':''}" title="Value ${v}"><span>${v}</span></div>`).join('');$('#sort-status').textContent=`Step ${idx+1} of ${steps.length}: ${step.note}`;$('#sort-explain').textContent=`Algorithm: ${algorithm.options[algorithm.selectedIndex].text}. Operations shown: ${Math.min(idx+1,steps.length)}. ${step.note}`;done=step.type==='done';$('#sort-step').disabled=done;$('#sort-run').disabled=done;}
function step(){if(idx<steps.length-1){idx++;draw();}}function load(){const parsed=valuesInput.value.split(',').map(x=>Number(x.trim()));if(parsed.length<2||parsed.length>12||parsed.some(n=>!Number.isFinite(n)||n<0||n>99)){toast('Enter 2–12 whole numbers between 0 and 99.','error');return;}values=parsed.map(n=>Math.floor(n));makeSteps();}$('#sort-load').onclick=load;algorithm.onchange=makeSteps;$('#sort-step').onclick=step;$('#sort-run').onclick=()=>{idx=steps.length-1;draw()};$('#sort-reset').onclick=()=>{idx=0;draw()};$('#save-sort').onclick=async()=>{if(!done){toast('Run the algorithm to completion before saving.','error');return;}try{await post('/api/labs/sorting-visualizer/complete',{result:{algorithm:algorithm.value,input:values,sorted:steps[steps.length-1].arr,operations:steps.length-1}});toast('Sorting lab saved.','success');}catch(e){toast(e.message,'error')}};makeSteps();}
function initSQL(){const students=[{id:1,name:'Avery Chen',course:'Computer Science'},{id:2,name:'Jordan Patel',course:'Data Science'},{id:3,name:'Sam Rivera',course:'Computer Science'},{id:4,name:'Riley Shah',course:'Physics'}];const courses=[{id:1,title:'Programming Fundamentals',subject:'Computer Science'},{id:2,title:'Data Querying',subject:'Data'},{id:3,title:'Applied Mathematics',subject:'Mathematics'}];const assessments=[{student_id:1,course_id:1,score:92},{student_id:2,course_id:2,score:86},{student_id:3,course_id:1,score:74},{student_id:4,course_id:3,score:89},{student_id:1,course_id:2,score:81}];let last=[];function execute(){const raw=$('#sql-query').value.trim();if(!/^select\s+/i.test(raw)||/[;].*\S/.test(raw.replace(/;\s*$/,''))||/\b(insert|update|delete|drop|alter|create|pragma|attach|detach|replace|union|exec|execute)\b/i.test(raw)){return showError('Only a single read-only SELECT query is supported. Writes and multiple statements are disabled.');}const q=raw.replace(/;\s*$/,'');let rows=[],columns=[];const joined=/\bjoin\b/i.test(q);if(joined){if(!/students\s+(?:as\s+\w+\s+)?(?:inner\s+)?join\s+courses\s+(?:as\s+\w+\s+)?on\s+\w*students?\.?id\s*=\s*\w*assessments?\.?student_id/i.test(q.replace(/\s+/g,' '))&&!/students.*join.*courses/i.test(q)){return showError('Try the provided JOIN example, or start with a query on one table.');}rows=assessments.map(a=>({...a,student_name:students.find(s=>s.id===a.student_id)?.name,course_title:courses.find(c=>c.id===a.course_id)?.title}));columns=['student_name','course_title','score','student_id','course_id'];}else{const m=q.match(/\bfrom\s+(students|courses|assessments)\b/i);if(!m)return showError('Choose one of the supported tables: students, courses, assessments.');const table=m[1].toLowerCase();rows=table==='students'?students.map(x=>({...x})):table==='courses'?courses.map(x=>({...x})):assessments.map(x=>({...x}));columns=Object.keys(rows[0]);}
const where=q.match(/\bwhere\s+([\w.]+)\s*(=|>=|<=|>|<|!=|like)\s*('?[^'\s;]+'?|\d+(?:\.\d+)?)/i);if(where){let key=where[1].split('.').pop(),op=where[2].toLowerCase(),val=where[3].replace(/^'|'$/g,'');if(!columns.includes(key))return showError(`Column “${key}” is not available in this query. Available: ${columns.join(', ')}.`);rows=rows.filter(r=>{let a=r[key],b=/^\d/.test(val)?Number(val):val;if(op==='=')return String(a).toLowerCase()===String(b).toLowerCase();if(op==='!=')return String(a).toLowerCase()!==String(b).toLowerCase();if(op==='like')return String(a).toLowerCase().includes(String(b).replace(/%/g,'').toLowerCase());return op==='>'?a>b:op==='<'?a<b:op==='>='?a>=b:a<=b;});}
const order=q.match(/\border\s+by\s+([\w.]+)(?:\s+(asc|desc))?/i);if(order){const key=order[1].split('.').pop();if(!columns.includes(key))return showError(`Cannot sort by “${key}”.`);rows.sort((a,b)=>(a[key]>b[key]?1:a[key]<b[key]?-1:0)*(order[2]?.toLowerCase()==='desc'?-1:1));}const limit=q.match(/\blimit\s+(\d+)/i);if(limit)rows=rows.slice(0,Math.min(50,Number(limit[1])));const sel=q.match(/^select\s+(.+?)\s+from\s+/i);if(sel&&sel[1].trim()!=='*'){const wanted=sel[1].split(',').map(s=>s.trim().split(/\s+as\s+/i)[0].split('.').pop());if(wanted.some(k=>!columns.includes(k)))return showError(`Unknown column. Available columns: ${columns.join(', ')}.`);rows=rows.map(r=>Object.fromEntries(wanted.map(k=>[k,r[k]])));columns=wanted;}last=rows;showRows(rows,columns);}
function showError(msg){$('#sql-result').innerHTML=`<div class="inline-note" style="background:#fff1ec;color:#a64d3d">${esc(msg)}</div>`;last=[];}function showRows(rows,cols){$('#sql-result').innerHTML=`<div class="helper-text" style="margin-bottom:8px">${rows.length} row(s) returned from sample data.</div>${rows.length?`<div class="sql-output"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:emptyState('No rows matched','Try a different WHERE condition.','⌕')}`;}
$('#sql-run').onclick=execute;$('#sql-example').onclick=()=>{$('#sql-query').value='SELECT name, score FROM assessments WHERE score >= 80 ORDER BY score DESC LIMIT 10;';execute()};$('#save-sql').onclick=async()=>{if(!last.length){toast('Run a query that returns at least one row before saving.','error');return;}try{await post('/api/labs/sql-playground/complete',{result:{query:$('#sql-query').value.slice(0,500),rowsReturned:last.length,mode:'restricted-sample-parser'}});toast('SQL practice saved.','success')}catch(e){toast(e.message,'error')}};}
async function renderSkillPath(){const [s,p,h]=await Promise.all([api('/api/skills'),api('/api/profile'),api('/api/labs/history')]);state.skills=s.skills;const profile=p.profile;const roles=[{name:'Software Developer',skills:['Programming fundamentals','Problem solving','SQL fundamentals','Algorithmic thinking','Version control']},{name:'Data Analyst',skills:['SQL fundamentals','Statistics','Data visualization','Spreadsheet analysis','Communication']},{name:'Machine Learning Engineer',skills:['Programming fundamentals','Statistics','Linear algebra','Algorithmic thinking','Model evaluation']},{name:'UI/UX Designer',skills:['User research','Wireframing','Prototyping','Visual design','Accessibility']},{name:'Cybersecurity Analyst',skills:['Networking','Operating systems','Security fundamentals','Scripting','Incident analysis']}];const selected=roles.find(r=>r.name===profile.career_goal)||roles[0];const evidence=new Map(s.skills.map(x=>[x.name.toLowerCase(),x]));const matched=selected.skills.filter(x=>evidence.has(x.toLowerCase()));const score=Math.round(matched.length/selected.skills.length*100);$('#main').innerHTML=pageHeader('MODULE 03 · CAREER DEVELOPMENT','SkillPath','Connect the skills you are practicing with a career direction. Roadmaps are frameworks for progress—not hiring predictions.',`<button class="btn btn-primary" id="add-skill-open">+ Add a skill</button>`)+`<div class="content-grid"><section class="surface">${surfaceTitle('Choose a career direction','The competency comparison updates to match your selection')}<div class="form-field"><label for="career-select">Target career</label><select id="career-select" class="career-select">${roles.map(r=>`<option ${r.name===profile.career_goal?'selected':''}>${r.name}</option>`).join('')}</select></div><div class="inline-note">${score}% of this illustrative framework has at least one matching skill entry. This is not a probability of employment or proof of proficiency.</div>${surfaceTitle('Competency comparison','Evidence status is shown for each role competency')}<div id="career-competencies">${renderCompetencies(selected,s.skills)}</div></section><section class="surface">${surfaceTitle('Your documented skills','Self-reported skills and lab-supported evidence are kept distinct')}${s.skills.length?s.skills.map(skill=>`<div class="skill-row"><div><strong>${esc(skill.name)}</strong><small>${esc(skill.evidence.replace(/-/g,' '))}</small></div><div class="skill-level" aria-label="Level ${skill.level} of 5">${[1,2,3,4,5].map(n=>`<i class="${n<=skill.level?'on':''}"></i>`).join('')}</div><div class="skill-score">${skill.level}/5</div></div>`).join(''):emptyState('Start your skills profile','Add a skill you are practicing or complete a LabSim activity to create supported evidence.','↗')}<div class="inline-note">Completing a tutorial or lab records practice evidence; it does not automatically certify professional proficiency.</div></section></div><section class="surface">${surfaceTitle('A practical roadmap','A suggested sequence based on the selected role')}<div class="roadmap-list">${selected.skills.map((skill,i)=>`<div class="roadmap-step"><strong>${i+1}. ${esc(skill)}</strong><p>${evidence.has(skill.toLowerCase())?'Existing record found. Revisit the evidence and try a more demanding task.':`Build a foundation in ${esc(skill.toLowerCase())}, then demonstrate it in a small project or assessment.`}</p></div>`).join('')}<div class="roadmap-step"><strong>Portfolio project</strong><p>Build one small project that combines two or more competencies. Document the problem, design choices, limitations, and what you would improve next.</p></div><div class="roadmap-step"><strong>Practice explaining your decisions</strong><p>Use the interview practice tool to rehearse a technical explanation. Feedback is guidance, not a hiring decision.</p></div></div><button class="btn btn-primary" id="interview-open">Practice an interview answer ↗</button></section><div id="skill-modal-host"></div>`;$('#career-select').onchange=async e=>{try{await put('/api/profile',{careerGoal:e.target.value});await renderSkillPath()}catch(err){toast(err.message,'error')}};$('#add-skill-open').onclick=()=>openSkillModal();$('#interview-open').onclick=()=>openInterviewModal();}
function renderCompetencies(role,skills){const found=new Map(skills.map(x=>[x.name.toLowerCase(),x]));return role.skills.map(name=>{const s=found.get(name.toLowerCase());return `<div class="skill-row"><div><strong>${esc(name)}</strong><small>${s?`Evidence: ${esc(s.evidence.replace(/-/g,' '))}`:'No matching evidence recorded'}</small></div><div class="skill-level">${[1,2,3,4,5].map(n=>`<i class="${s&&n<=s.level?'on':''}"></i>`).join('')}</div><div class="skill-score">${s?'Tracked':'To build'}</div></div>`}).join('');}
function openSkillModal(){const host=$('#skill-modal-host');host.innerHTML=`<div class="modal-backdrop" id="skill-modal"><section class="auth-card" role="dialog" aria-modal="true" aria-labelledby="skill-modal-title"><button class="modal-close" id="skill-close" aria-label="Close">×</button><h2 id="skill-modal-title">Add a skill to your profile.</h2><p class="auth-intro">This entry is marked self-reported unless a supported platform activity supplies evidence.</p><form id="skill-form"><div class="form-field"><label for="skill-name">Skill name</label><input id="skill-name" required maxlength="80" placeholder="e.g. Python fundamentals"></div><div class="form-field"><label for="skill-level">Current self-assessed level</label><select id="skill-level" class="field-control"><option value="1">1 — Exploring</option><option value="2">2 — Learning</option><option value="3">3 — Practicing</option><option value="4">4 — Confident</option><option value="5">5 — Can explain and apply</option></select></div><button class="btn btn-primary btn-block" type="submit">Save skill</button></form></section></div>`;$('#skill-close').onclick=()=>host.innerHTML='';$('#skill-form').onsubmit=async e=>{e.preventDefault();try{await post('/api/skills',{name:$('#skill-name').value,level:Number($('#skill-level').value)});toast('Skill saved.','success');await renderSkillPath()}catch(err){toast(err.message,'error')}};}
function openInterviewModal(){const host=$('#skill-modal-host');host.innerHTML=`<div class="modal-backdrop" id="interview-modal"><section class="auth-card" role="dialog" aria-modal="true" aria-labelledby="interview-title"><button class="modal-close" id="interview-close" aria-label="Close">×</button><div class="auth-brand">SKILLPATH · PRACTICE</div><h2 id="interview-title">Practice explaining your thinking.</h2><p class="auth-intro">Your answer is saved for review. If live AI is not configured, a local fallback provides general coaching guidance.</p><form id="interview-form"><div class="form-field"><label for="interview-role">Target role</label><select id="interview-role" class="field-control"><option>Software Developer</option><option>Data Analyst</option><option>Machine Learning Engineer</option><option>UI/UX Designer</option><option>Cybersecurity Analyst</option></select></div><div class="form-field"><label for="interview-topic">Interview topic</label><input id="interview-topic" required value="problem solving" maxlength="80"></div><div class="form-field"><label for="interview-answer">Your answer</label><textarea id="interview-answer" rows="4" maxlength="2000" required placeholder="Explain the concept and give an example…"></textarea></div><button class="btn btn-primary btn-block" type="submit">Review my answer ↗</button></form><div id="interview-result"></div></section></div>`;$('#interview-close').onclick=()=>host.innerHTML='';$('#interview-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const r=await post('/api/interview',{role:$('#interview-role').value,topic:$('#interview-topic').value,answer:$('#interview-answer').value});$('#interview-result').innerHTML=`<div class="inline-note"><strong>${r.mode==='live-ai'?'Live AI coaching':'Local fallback coaching'}</strong><br>${esc(r.feedback).replace(/\n/g,'<br>')}</div><button class="mini-btn" id="interview-done">Close and refresh roadmap</button>`;$('#interview-done').onclick=()=>renderSkillPath();}catch(err){toast(err.message,'error');btn.disabled=false}};}
async function renderClassPulse(){const [data,users]=await Promise.all([api('/api/classpulse/records'),api('/api/classpulse/students')]);state.classpulse=data;state.students=users.students;const open=data.alerts.filter(a=>a.status!=='resolved');$('#main').innerHTML=pageHeader('MODULE 02 · ACADEMIC SUPPORT','ClassPulse','Review authorized academic records, understand the rule behind an indicator, and record a supportive follow-up.',`<button class="btn btn-primary" id="record-open">+ Add academic record</button>`)+`<div class="inline-note">Current review rules: assessment below 50% and attendance below 75% trigger an attention alert. These configurable starter thresholds are prompts for human review—not validated predictions. This workspace is currently administrator-only until institution/course assignment controls are configured.</div><div class="stats-grid"><article class="stat-card"><div class="stat-head">Academic records <span class="stat-icon stat-purple">▦</span></div><div class="stat-value">${data.records.length}</div><div class="stat-note">Stored attendance and assessment entries</div></article><article class="stat-card"><div class="stat-head">Open indicators <span class="stat-icon stat-peach">⌁</span></div><div class="stat-value">${open.length}</div><div class="stat-note">Require authorized review</div></article><article class="stat-card"><div class="stat-head">Students in system <span class="stat-icon stat-blue">◉</span></div><div class="stat-value">${users.students.length}</div><div class="stat-note">Accounts with student role</div></article><article class="stat-card"><div class="stat-head">Resolved indicators <span class="stat-icon stat-mint">✓</span></div><div class="stat-value">${data.alerts.filter(a=>a.status==='resolved').length}</div><div class="stat-note">Marked resolved by staff</div></article></div><section class="surface" style="margin-bottom:16px">${surfaceTitle('Academic support indicators','Evidence and rule are displayed for every alert')}${data.alerts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Subject</th><th>Level</th><th>Evidence / rule</th><th>Status</th><th>Action</th></tr></thead><tbody>${data.alerts.map(a=>`<tr><td>${esc(a.student_name)}</td><td>${esc(a.subject)}</td><td><span class="status-badge attention">${esc(a.level)}</span></td><td>${esc(a.explanation)}${a.intervention?`<br><span class="muted-cell">Intervention: ${esc(a.intervention)}</span>`:''}</td><td>${esc(a.status)}</td><td><button class="mini-btn" data-alert-id="${a.id}">Review / update</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No indicators have been generated','Add an academic record. Indicators appear only when a documented rule is met.','⌁')}</section><section class="surface">${surfaceTitle('Recent academic records','Values are stored with a source date')}${data.records.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Subject</th><th>Type</th><th>Value</th><th>Recorded</th></tr></thead><tbody>${data.records.slice(0,80).map(r=>`<tr><td>${esc(r.student_name)}</td><td>${esc(r.subject)}</td><td>${esc(r.record_type)}</td><td>${r.record_type==='attendance'?r.value+'%':r.value+'/'+r.max_value}</td><td>${esc(r.recorded_on)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No records yet','Create a record for a student to begin an evidence-based review.','▦')}</section><div id="classpulse-modal-host"></div>`;$('#record-open').onclick=openRecordModal;$$('[data-alert-id]').forEach(b=>b.onclick=()=>openAlertModal(data.alerts.find(a=>a.id===Number(b.dataset.alertId))));}
function openRecordModal(){const host=$('#classpulse-modal-host');host.innerHTML=`<div class="modal-backdrop"><section class="auth-card" role="dialog" aria-modal="true" aria-labelledby="record-title"><button class="modal-close" id="record-close" aria-label="Close">×</button><h2 id="record-title">Add an academic record.</h2><p class="auth-intro">Use an authorized, verified record. Values are not predictions.</p><form id="record-form"><div class="form-field"><label for="record-student">Student</label><select class="field-control" id="record-student" required>${state.students.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.email)}</option>`).join('')}</select></div><div class="form-field"><label for="record-subject">Subject</label><input id="record-subject" required maxlength="80" placeholder="e.g. Mathematics"></div><div class="form-field"><label for="record-type">Record type</label><select id="record-type" class="field-control"><option value="assessment">Assessment score</option><option value="attendance">Attendance percentage</option></select></div><div class="form-field"><label for="record-value">Value</label><input id="record-value" type="number" min="0" step="0.01" required value="40"></div><div class="form-field" id="record-max-wrap"><label for="record-max">Maximum score</label><input id="record-max" type="number" min="0.01" step="0.01" value="100"></div><div class="form-field"><label for="record-date">Record date</label><input id="record-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><button class="btn btn-primary btn-block" type="submit">Save record and evaluate rules</button></form></section></div>`;$('#record-close').onclick=()=>host.innerHTML='';$('#record-type').onchange=()=>$('#record-max-wrap').classList.toggle('hidden',$('#record-type').value==='attendance');$('#record-form').onsubmit=async e=>{e.preventDefault();const body={studentId:Number($('#record-student').value),subject:$('#record-subject').value,type:$('#record-type').value,value:Number($('#record-value').value),maxValue:$('#record-type').value==='assessment'?Number($('#record-max').value):null,date:$('#record-date').value};try{await post('/api/classpulse/records',body);toast('Academic record saved and rules evaluated.','success');await renderClassPulse()}catch(err){toast(err.message,'error')}};}
function openAlertModal(a){const host=$('#classpulse-modal-host');host.innerHTML=`<div class="modal-backdrop"><section class="auth-card" role="dialog" aria-modal="true" aria-labelledby="alert-title"><button class="modal-close" id="alert-close" aria-label="Close">×</button><h2 id="alert-title">Review academic indicator.</h2><p class="auth-intro">${esc(a.student_name)} · ${esc(a.subject)} · ${esc(a.level)}</p><div class="inline-note">Evidence: ${esc(a.explanation)}</div><form id="alert-form"><div class="form-field"><label for="alert-status">Review status</label><select id="alert-status" class="field-control"><option value="open" ${a.status==='open'?'selected':''}>Open</option><option value="reviewing" ${a.status==='reviewing'?'selected':''}>Reviewing</option><option value="resolved" ${a.status==='resolved'?'selected':''}>Resolved</option></select></div><div class="form-field"><label for="alert-intervention">Support action / review notes</label><textarea id="alert-intervention" rows="3" maxlength="600">${esc(a.intervention||'')}</textarea></div><div class="form-field"><label for="alert-follow">Follow-up date (optional)</label><input id="alert-follow" type="date" value="${esc(a.follow_up||'')}"></div><button class="btn btn-primary btn-block" type="submit">Save review</button></form></section></div>`;$('#alert-close').onclick=()=>host.innerHTML='';$('#alert-form').onsubmit=async e=>{e.preventDefault();try{await patch(`/api/classpulse/alerts/${a.id}`,{status:$('#alert-status').value,intervention:$('#alert-intervention').value,followUp:$('#alert-follow').value});toast('Review updated.','success');await renderClassPulse()}catch(err){toast(err.message,'error')}};}
async function renderCampusAccess(){const p=await api('/api/profile');const a=p.profile.accessibility||{};$('#main').innerHTML=pageHeader('MODULE 05 · INCLUSIVE LEARNING','CampusAccess','Adjust how the interface reads and moves. These settings are optional, private, and can be changed at any time.')+`<div class="content-grid"><section class="surface">${surfaceTitle('Reading comfort','Preferences are saved to your profile and applied across the workspace')}<div class="setting-row"><div><strong>Text size</strong><p>Increase or reduce interface text.</p></div><div style="width:160px"><input id="access-font" type="range" min="0.85" max="1.35" step="0.05" value="${a.fontScale||1}" style="width:100%;accent-color:#7868ed"><div class="helper-text" id="access-font-label">${Math.round((a.fontScale||1)*100)}% of default</div></div></div><div class="setting-row"><div><strong>Line spacing</strong><p>Make longer text easier to follow.</p></div><select id="access-spacing" class="career-select"><option value="1.3" ${a.lineSpacing===1.3?'selected':''}>Compact</option><option value="1.6" ${!a.lineSpacing||a.lineSpacing===1.6?'selected':''}>Comfortable</option><option value="2" ${a.lineSpacing===2?'selected':''}>Expanded</option></select></div><div class="setting-row"><div><strong>High contrast</strong><p>Increase visual contrast for key interface elements.</p></div><label class="toggle-control"><input id="access-contrast" type="checkbox" ${a.highContrast?'checked':''}> Enabled</label></div><div class="setting-row"><div><strong>Reduced motion</strong><p>Reduce non-essential animation and transitions.</p></div><label class="toggle-control"><input id="access-motion" type="checkbox" ${a.reducedMotion?'checked':''}> Enabled</label></div><div class="setting-row"><div><strong>Color theme</strong><p>Choose light or dark workspace appearance.</p></div><select id="access-theme" class="career-select"><option value="light" ${a.theme!=='dark'?'selected':''}>Light</option><option value="dark" ${a.theme==='dark'?'selected':''}>Dark</option></select></div><button class="btn btn-primary" id="save-access" style="margin-top:17px">Save accessibility preferences ↗</button><p class="helper-text" style="margin-top:12px">You do not need to disclose a diagnosis or disability to use these options. These settings improve supported interface behavior; they do not guarantee full WCAG conformance on their own.</p></section><section class="surface">${surfaceTitle('Preview your preferences','This sample updates when you change the controls')}<div class="module-banner" id="access-preview"><div class="page-kicker">READING PREVIEW</div><h2>A clearer way to learn.</h2><p>Readable spacing, adjustable text, and calmer motion can help make a learning session more comfortable. Try changing the settings and saving to apply them across the workspace.</p><button class="btn btn-primary" style="margin-top:14px" id="access-preview-btn">Example action</button></div><div class="inline-note">Keyboard support: use Tab to move between controls, Enter or Space to activate buttons, and browser zoom to enlarge the full page. A skip link is available at the top of the document.</div></section></div>`;const preview=()=>{const f=Number($('#access-font').value);$('#access-font-label').textContent=Math.round(f*100)+'% of default';$('#access-preview').style.fontSize=`${f}em`;$('#access-preview').style.lineHeight=$('#access-spacing').value;$('#access-preview').style.filter=$('#access-contrast').checked?'contrast(1.15)':'';};$('#access-font').oninput=preview;$('#access-spacing').onchange=preview;$('#access-contrast').onchange=preview;$('#save-access').onclick=async()=>{try{const settings={fontScale:Number($('#access-font').value),lineSpacing:Number($('#access-spacing').value),highContrast:$('#access-contrast').checked,reducedMotion:$('#access-motion').checked,theme:$('#access-theme').value};const r=await put('/api/accessibility',settings);applyAccessibility(r.settings);toast('Accessibility preferences saved.','success');}catch(e){toast(e.message,'error')}};$('#access-preview-btn').onclick=()=>toast('Preview action works. Preferences can be saved below.');preview();}
function applyAccessibility(a){if(!a)return;document.documentElement.style.setProperty('--font-scale',String(a.fontScale||1));document.documentElement.style.setProperty('--line-spacing',String(a.lineSpacing||1.6));document.body.classList.toggle('high-contrast',Boolean(a.highContrast));document.body.classList.toggle('reduce-motion',Boolean(a.reducedMotion));document.body.classList.toggle('theme-dark',a.theme==='dark');}
async function renderHub(){const [d,r,h,p,l]=await Promise.all([api('/api/dashboard'),api('/api/recommendations'),api('/api/labs/history'),api('/api/profile'),api('/api/quizzes/history')]);state.recommendations=r.recommendations;const todo=r.recommendations.filter(x=>['available','accepted','in_progress'].includes(x.status));$('#recommendation-dot').style.display=todo.length?'block':'none';const completed=r.recommendations.filter(x=>x.status==='completed').length;const labs=h.attempts.filter(x=>x.completed).length;const quizzes=l.attempts.length;$('#main').innerHTML=pageHeader('MODULE 06 · CROSS-MODULE INTELLIGENCE','Learning Intelligence Hub','A connected view of learning, practical activity, career goals, and your next useful actions.')+`<div class="dashboard-welcome"><div class="welcome-art"></div><div class="welcome-copy"><div class="welcome-overline">YOUR LEARNING SNAPSHOT</div><h2>Progress you can explain.</h2><p>Your plan combines saved learning activity with your stated goals. Suggestions are based on available records; missing data is not treated as zero performance.</p></div><button class="btn welcome-action" data-page="settings">Review my goals ↗</button></div><div class="stats-grid"><article class="stat-card"><div class="stat-head">Quiz attempts <span class="stat-icon stat-purple">◈</span></div><div class="stat-value">${quizzes}</div><div class="stat-note">LearnBridge recorded attempts</div></article><article class="stat-card"><div class="stat-head">Practical labs <span class="stat-icon stat-blue">⌘</span></div><div class="stat-value">${labs}</div><div class="stat-note">LabSim completions</div></article><article class="stat-card"><div class="stat-head">Skills tracked <span class="stat-icon stat-peach">↗</span></div><div class="stat-value">${d.stats.skillsTracked}</div><div class="stat-note">Declared and activity-supported</div></article><article class="stat-card"><div class="stat-head">Actions completed <span class="stat-icon stat-mint">✓</span></div><div class="stat-value">${completed}</div><div class="stat-note">Recommendations marked complete</div></article></div><div class="content-grid"><section class="surface">${surfaceTitle('Recommended next steps','Each action includes a reason and source module')}${todo.length?todo.map(recommendationCard).join(''):emptyState('No open recommendations','Complete a lesson or lab to generate relevant next steps from recorded activity.','✳')}</section><section class="surface">${surfaceTitle('Your current direction','From your saved profile')}<div class="recommendation-card"><span class="source-pill">LEARNING GOAL</span><h3>${esc(p.profile.goals||'Build consistent learning habits')}</h3><p>Career goal: ${esc(p.profile.career_goal||'Not set')}</p><p>Subjects: ${(p.profile.subjects||[]).map(esc).join(', ')||'Not set'}</p><button class="mini-btn primary" data-page="settings">Edit goals</button></div><div class="inline-note">The Hub does not change official grades, attendance, roles, or permissions. Academic support records are restricted by role.</div></section></div><div class="content-grid equal"><section class="surface">${surfaceTitle('Cross-module activity','Meaningful events from your account')}${d.events.length?`<div class="activity-list">${d.events.map(e=>`<div class="activity-row"><span class="activity-dot">${e.module==='LabSim'?'⌘':e.module==='SkillPath'?'↗':'◈'}</span><div class="activity-copy"><strong>${esc(e.event_type.replace(/[._]/g,' '))}</strong><small>${esc(e.module)}${e.metadata?.quiz?' · '+esc(e.metadata.quiz.replace(/-/g,' ')):''}</small></div><span class="activity-time">${dateShort(e.created_at)}</span></div>`).join('')}</div>`:emptyState('No activity to review','Your timeline updates as you use the platform.','↗')}</section><section class="surface">${surfaceTitle('Weekly plan starter','A suggested sequence you can adjust yourself')}<div class="roadmap-list"><div class="roadmap-step"><strong>1. Focused learning session</strong><p>Choose one LearnBridge topic connected to your current goals. Allow 15–20 minutes if that fits your schedule.</p></div><div class="roadmap-step"><strong>2. Practice what you learned</strong><p>Complete the matching quiz or a LabSim experiment. Review the result rather than rushing to the next task.</p></div><div class="roadmap-step"><strong>3. Connect it to a skill</strong><p>Record relevant evidence in SkillPath and decide what to practice next.</p></div></div><p class="helper-text">This is a suggested sequence, not a calendar based on unavailable schedule data. Add your availability in your own planner before committing time.</p><button class="btn btn-primary" data-page="learnbridge">Start a learning session ↗</button></section></div>`;bindPageButtons();bindRecommendationActions();}
async function renderStudentAcademic(){const d=await api('/api/my-academics');const x=d.summary;const attendance=x.averageAttendance===null?'—':x.averageAttendance+'%';const marks=x.averageMarks===null?'—':x.averageMarks+'%';const estimate=x.estimatedNextExamScore;$('#main').innerHTML=pageHeader('SPACE 02 · ACADEMIC DASHBOARD','Your academic picture','Track your own attendance and assessment marks, review the trend, and use a transparent estimate to plan what to revise.',`<button class="btn btn-primary" id="academic-add">+ Add a record</button>`)+`<div class="stats-grid"><article class="stat-card"><div class="stat-head">Average attendance</div><div class="stat-value">${attendance}</div><div class="stat-note">Across ${x.attendanceCount} attendance record(s)</div></article><article class="stat-card"><div class="stat-head">Average assessment</div><div class="stat-value">${marks}</div><div class="stat-note">Normalized percentage across saved marks</div></article><article class="stat-card"><div class="stat-head">Next-exam planning estimate</div><div class="stat-value">${estimate===null?'Add data':estimate+'%'}</div><div class="stat-note">Transparent heuristic, not a guarantee</div></article><article class="stat-card"><div class="stat-head">Records saved</div><div class="stat-value">${d.records.length}</div><div class="stat-note">Only records attached to your account</div></article></div><div class="content-grid"><section class="surface">${surfaceTitle('Score planning estimate','How this number is calculated')}<div class="estimate-number">${estimate===null?'—':estimate+'%'}</div>${estimate===null?'<p>Add at least one assessment record to calculate a planning estimate. Attendance can refine it when available.</p>':`<div class="estimate-meter"><span style="width:${estimate}%"></span></div><p>${x.method}</p>`}<div class="inline-note">This is a simple planning heuristic, not a validated prediction model. It does not account for exam difficulty, syllabus coverage, marking differences, health, or study time. Use it to plan—not as a promise of your result.</div></section><section class="surface">${surfaceTitle('A practical next step','Use your records to decide what to do next')}<div class="roadmap-list"><div class="roadmap-step"><strong>1. Check the evidence</strong><p>Confirm that the attendance and marks you entered are correct and use the same grading scale.</p></div><div class="roadmap-step"><strong>2. Find the subject gap</strong><p>Open LearnBridge and complete a knowledge check for a topic where your marks or confidence are lower.</p></div><div class="roadmap-step"><strong>3. Practise and review</strong><p>Use StudyShelf for explanations and LabSim for practical subjects, then update your evidence.</p></div></div><button class="btn btn-primary" data-page="learnbridge">Start a learning check ↗</button></section></div><section class="surface" style="margin-top:16px">${surfaceTitle('Your academic records','Records are private to your account; staff cannot use this student form to impersonate your entries.')}${d.records.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Subject</th><th>Type</th><th>Value</th><th>Date</th></tr></thead><tbody>${d.records.map(r=>`<tr><td>${esc(r.subject)}</td><td>${esc(r.record_type)}</td><td>${r.record_type==='attendance'?r.value+'%':r.value+'/'+r.max_value}</td><td>${esc(r.recorded_on)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No academic records yet','Add your attendance percentage and assessment marks to start seeing your academic picture.','⌁')}</section><div id="academic-modal-host"></div>`;$('#academic-add').onclick=openStudentAcademicModal;bindPageButtons();}
function openStudentAcademicModal(){const host=$('#academic-modal-host');host.innerHTML=`<div class="modal-backdrop"><section class="auth-card" role="dialog" aria-modal="true"><button class="modal-close" id="academic-close" aria-label="Close dialog">×</button><div class="auth-brand">ACADEMIC DASHBOARD</div><h2>Add your academic record</h2><p class="auth-intro">Enter accurate records. For attendance, enter a percentage from 0 to 100. For marks, enter both the score and maximum score.</p><form id="academic-form" class="academic-form"><div class="form-field full"><label for="academic-subject">Subject</label><input id="academic-subject" required maxlength="80" placeholder="e.g. Mathematics"></div><div class="form-field"><label for="academic-type">Record type</label><select id="academic-type" class="field-control"><option value="attendance">Attendance (%)</option><option value="assessment">Assessment marks</option></select></div><div class="form-field"><label for="academic-value">Value / score</label><input id="academic-value" type="number" required min="0" max="100" step="0.1" value="80"></div><div class="form-field" id="academic-max-wrap"><label for="academic-max">Maximum marks</label><input id="academic-max" type="number" min="1" step="0.1" value="100"></div><div class="form-field"><label for="academic-date">Record date</label><input id="academic-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="form-field full"><button class="btn btn-primary btn-block" type="submit">Save academic record ↗</button></div><p class="form-error full" id="academic-error"></p></form></section></div>`;const overlay=host.firstElementChild;$('#academic-close').onclick=()=>host.innerHTML='';overlay.addEventListener('click',e=>{if(e.target===overlay)host.innerHTML=''});$('#academic-type').onchange=()=>{$('#academic-max-wrap').style.display=$('#academic-type').value==='assessment'?'':'none';$('#academic-value').max=$('#academic-type').value==='attendance'?'100':'';};$('#academic-type').dispatchEvent(new Event('change'));$('#academic-form').onsubmit=async e=>{e.preventDefault();try{await post('/api/my-academics',{subject:$('#academic-subject').value,type:$('#academic-type').value,value:Number($('#academic-value').value),maxValue:$('#academic-type').value==='assessment'?Number($('#academic-max').value):null,date:$('#academic-date').value});host.innerHTML='';toast('Academic record saved.','success');await renderStudentAcademic();}catch(err){$('#academic-error').textContent=err.message;}};}
async function renderStudyShelf(){const data=await api('/api/lessons');state.lessons=data.lessons;const materials=[...data.lessons.map(l=>({id:l.id,title:l.title,subject:l.subject,tag:l.tag,level:l.level,summary:l.summary,duration:l.duration,kind:'Guided lesson'})),{id:'math-foundations',title:'Mathematics: concepts to practice',subject:'Mathematics',tag:'Foundations',level:'Beginner',summary:'A structured way to review definitions, work through one solved example, and then attempt practice independently.',duration:'15 min',kind:'Study guide'},{id:'chemistry-basics',title:'Chemistry: reactions and measurements',subject:'Chemistry',tag:'Lab preparation',level:'Beginner',summary:'Review units, variables, balanced equations, observation notes, and safe practical-learning habits before a lab.',duration:'12 min',kind:'Study guide'},{id:'physics-basics',title:'Physics: model, calculate, explain',subject:'Physics',tag:'Problem solving',level:'Beginner',summary:'Identify known values, select a formula, check units, calculate, and explain whether the result makes physical sense.',duration:'10 min',kind:'Study guide'},{id:'study-method',title:'How to study a difficult topic',subject:'Study skills',tag:'Learning strategy',level:'All levels',summary:'Use retrieval practice, short focused sessions, worked examples, and spaced review instead of only rereading notes.',duration:'8 min',kind:'Study guide'}];$('#main').innerHTML=pageHeader('SPACE 05 · LEARNING MATERIALS','StudyShelf','Find a starting point for your subject, open guided lessons, and use structured study guides to learn at your own pace.')+`<div class="material-search"><input id="material-query" type="search" placeholder="Search subject, topic, or keyword…" aria-label="Search learning materials"><select id="material-subject" class="career-select" aria-label="Filter by subject"><option value="all">All subjects</option>${[...new Set(materials.map(m=>m.subject))].map(v=>`<option>${esc(v)}</option>`).join('')}</select></div><div id="material-results" class="material-grid"></div><section class="surface" style="margin-top:16px">${surfaceTitle('A better way to use a study resource','A repeatable learning routine')}<div class="roadmap-list"><div class="roadmap-step"><strong>Understand</strong><p>Read the explanation and write down the main idea in your own words.</p></div><div class="roadmap-step"><strong>Practise</strong><p>Try an example without looking at the answer, then compare your reasoning.</p></div><div class="roadmap-step"><strong>Check</strong><p>Use a quiz or lab, and revisit the topic if you cannot explain why the answer works.</p></div></div><button class="btn btn-primary" data-page="learnbridge">Open adaptive lessons ↗</button></section>`;const draw=()=>{const q=$('#material-query').value.toLowerCase().trim(),sub=$('#material-subject').value;const rows=materials.filter(m=>(sub==='all'||m.subject===sub)&&(!q||[m.title,m.subject,m.tag,m.summary].join(' ').toLowerCase().includes(q)));$('#material-results').innerHTML=rows.length?rows.map(m=>`<article class="material-card"><span class="material-tag">${esc(m.kind)} · ${esc(m.subject)}</span><h3>${esc(m.title)}</h3><p>${esc(m.summary)}</p><div class="lesson-meta"><span>${esc(m.level)}</span><span>${esc(m.duration)}</span></div>${m.id=== 'math-foundations'||m.id==='chemistry-basics'||m.id==='physics-basics'||m.id==='study-method'?`<button class="btn btn-quiet" data-material-read="${m.id}">Open study guide ↗</button>`:`<button class="btn btn-primary" data-material-lesson="${m.id}">Open lesson ↗</button>`}</article>`).join(''):emptyState('No matching materials','Try a different keyword or choose All subjects.','▤');$$('[data-material-lesson]').forEach(b=>b.onclick=()=>{state.activeLesson=b.dataset.materialLesson;navigate('learnbridge')});$$('[data-material-read]').forEach(b=>b.onclick=()=>{const m=materials.find(x=>x.id===b.dataset.materialRead);const host=document.createElement('div');host.className='modal-backdrop';host.innerHTML=`<section class="auth-card" role="dialog" aria-modal="true"><button class="modal-close" aria-label="Close guide">×</button><div class="auth-brand">STUDYSHELF · STUDY GUIDE</div><h2>${esc(m.title)}</h2><p>${esc(m.summary)}</p><div class="inline-note">Study workflow: (1) write down the key concept, (2) create one worked example, (3) solve a new problem without notes, (4) explain the result, and (5) revisit the topic after a delay.</div><button class="btn btn-primary btn-block">Done</button></section>`;document.body.append(host);host.querySelector('.modal-close').onclick=()=>host.remove();host.querySelector('.btn-primary').onclick=()=>host.remove();host.addEventListener('click',e=>{if(e.target===host)host.remove()});});};$('#material-query').oninput=draw;$('#material-subject').onchange=draw;draw();bindPageButtons();}
async function renderSettings(){const p=await api('/api/profile');const x=p.profile;$('#main').innerHTML=pageHeader('YOUR ACCOUNT · PREFERENCES','Settings','Manage your learning profile and the goals that help personalize your workspace.')+`<div class="content-grid"><section class="surface">${surfaceTitle('Learning profile','Only provide information you want to use for your learning plan')}<form id="profile-form" class="profile-form"><div class="form-field"><label for="profile-name">Account name</label><input id="profile-name" value="${esc(state.user.name)}" disabled><span class="helper-text">Contact an administrator if your account name needs to change.</span></div><div class="form-field"><label for="profile-email">Email address</label><input id="profile-email" value="${esc(state.user.email)}" disabled></div><div class="form-field"><label for="profile-institution">Institution (optional)</label><input id="profile-institution" maxlength="120" value="${esc(x.institution)}" placeholder="School or institution"></div><div class="form-field"><label for="profile-course">Course / program (optional)</label><input id="profile-course" maxlength="120" value="${esc(x.course)}" placeholder="e.g. Computer Science"></div><div class="form-field"><label for="profile-semester">Current semester (optional)</label><input id="profile-semester" maxlength="40" value="${esc(x.semester)}" placeholder="e.g. Semester 2"></div><div class="form-field"><label for="profile-career">Career goal</label><select id="profile-career" class="field-control">${['Software Developer','Data Analyst','Machine Learning Engineer','UI/UX Designer','Cybersecurity Analyst','Not sure yet'].map(v=>`<option ${v===x.career_goal?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-field full"><label for="profile-goals">Current learning goal</label><textarea id="profile-goals" maxlength="300" placeholder="What would you like to make progress on?">${esc(x.goals)}</textarea></div><div class="form-field full"><label for="profile-subjects">Focus subjects (comma separated)</label><input id="profile-subjects" maxlength="400" value="${esc((x.subjects||[]).join(', '))}" placeholder="Computer Science, Mathematics"><span class="helper-text">Choose subjects relevant to you. You can update this whenever your focus changes.</span></div><div class="form-field full"><button class="btn btn-primary" type="submit">Save profile changes ↗</button></div></form></section><section class="surface">${surfaceTitle('Account & privacy','Understand how your account is used')}<div class="activity-list"><div class="activity-row"><span class="activity-dot">⌑</span><div class="activity-copy"><strong>Account role</strong><small>${esc(state.user.role)} · assigned by the server, not editable here</small></div></div><div class="activity-row"><span class="activity-dot">◉</span><div class="activity-copy"><strong>Academic privacy</strong><small>Student accounts cannot access restricted ClassPulse records.</small></div></div><div class="activity-row"><span class="activity-dot">✦</span><div class="activity-copy"><strong>AI settings</strong><small>AI provider keys are configured by the site operator and never sent to the browser.</small></div></div></div><div class="inline-note">Data stored includes your account, learning profile, quiz attempts, saved lab results, skills, preferences, and activity events. Avoid entering sensitive personal details into free-text fields.</div><button class="btn btn-quiet" id="open-accessibility">Adjust accessibility settings ↗</button>${state.user.role==='admin'?'<div class="inline-note">Administrator tools are enabled for this account.</div><a class="btn btn-quiet" href="/api/admin/export" target="_blank" rel="noreferrer">Export authorized data ↗</a>':''}</section></div>`;$('#profile-form').onsubmit=async e=>{e.preventDefault();try{const subjects=$('#profile-subjects').value.split(',').map(x=>x.trim()).filter(Boolean);await put('/api/profile',{institution:$('#profile-institution').value,course:$('#profile-course').value,semester:$('#profile-semester').value,careerGoal:$('#profile-career').value,goals:$('#profile-goals').value,subjects});toast('Profile saved.','success');state.profile=(await api('/api/profile')).profile;}catch(err){toast(err.message,'error')}};$('#open-accessibility').onclick=()=>navigate('campusaccess');}
function renderHelp(){$('#main').innerHTML=pageHeader('SUPPORT · GETTING STARTED','Help & guidance','A quick guide to using the platform and understanding what its indicators mean.')+`<div class="help-grid"><article class="help-card"><span class="help-icon">◈</span><h3>How do recommendations work?</h3><p>Recommendations are generated from saved learning activity and documented rules. Each one shows a reason and a suggested action. You can accept, complete, or dismiss it.</p></article><article class="help-card"><span class="help-icon">⌁</span><h3>What is an academic alert?</h3><p>ClassPulse indicators are prompts for authorized educator review. They include the record and rule that triggered them; they are not a diagnosis or a prediction about a student's future.</p></article><article class="help-card"><span class="help-icon">✦</span><h3>Is the learning assistant live AI?</h3><p>Only when the operator configures an AI-compatible provider. The interface labels live AI versus local fallback guidance so simulated responses are not presented as a model result.</p></article><article class="help-card"><span class="help-icon">⌘</span><h3>Are labs connected to real equipment?</h3><p>No. The initial Ohm’s Law, sorting, and SQL labs are browser-based educational simulations. The circuit uses an idealized calculation and the SQL lab uses constrained sample data.</p></article><article class="help-card"><span class="help-icon">◉</span><h3>How do I make the interface easier to read?</h3><p>Open CampusAccess to change text size, contrast, theme, line spacing, and reduced motion. You do not need to disclose a disability to use these settings.</p></article><article class="help-card"><span class="help-icon">⚙</span><h3>What does publishing require?</h3><p>Use a persistent server, HTTPS, a strong SESSION_SECRET, a backup plan, and a configured database. Review SECURITY.md and DEPLOYMENT.md before using real student data.</p></article></div><section class="surface" style="margin-top:15px">${surfaceTitle('Need to check system status?')}<p class="helper-text">The health endpoint reports whether the app is running and whether an AI provider is configured. It does not expose API keys.</p><a class="btn btn-primary" href="/api/health" target="_blank" rel="noreferrer">Open system status ↗</a></section>`;}
function bindPageButtons(){ $$('[data-page]').forEach(b=>{if(b.dataset.pageBound)return;b.dataset.pageBound='1';b.addEventListener('click',()=>navigate(b.dataset.page));}); }
function showSidebar(){ $('#sidebar').classList.add('open');$('#sidebar-scrim').classList.remove('hidden'); }
async function boot(){ $('#year').textContent=new Date().getFullYear();$('#login-open').onclick=()=>openAuth('login');$('#register-open').onclick=()=>openAuth('register');$('#hero-start').onclick=$('#how-start').onclick=$('#final-start').onclick=()=>openAuth('register');$$('[data-module-start]').forEach(b=>b.addEventListener('click',()=>{const page=b.dataset.moduleStart;if(state.user)navigate(page);else{state.pendingPage=page;openAuth('register');}}));$('#auth-close').onclick=closeAuth;$('#auth-modal').addEventListener('click',e=>{if(e.target===$('#auth-modal'))closeAuth()});$$('[data-auth-mode]').forEach(b=>b.onclick=()=>setAuthMode(b.dataset.authMode));$('#auth-form').onsubmit=async e=>{e.preventDefault();const btn=$('#auth-submit');btn.disabled=true;$('#auth-error').textContent='';const mode=state.authMode;try{const payload={email:$('#auth-email').value,password:$('#auth-password').value};if(mode==='register')payload.name=$('#auth-name').value;const result=await post(mode==='register'?'/api/auth/register':'/api/auth/login',payload);showApp(result.user);toast(mode==='register'?'Your learning space is ready.':'Welcome back.','success');}catch(err){$('#auth-error').textContent=err.message;}finally{btn.disabled=false}};$('#logout-btn').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'});}catch{}state.user=null;state.activeLesson=null;showPublic();toast('You have signed out.','success')};$('#mobile-menu').onclick=showSidebar;$('#sidebar-close').onclick=()=>{$('#sidebar').classList.remove('open');$('#sidebar-scrim').classList.add('hidden')};$('#sidebar-scrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#sidebar-scrim').classList.add('hidden')};$('#topbar-profile').onclick=()=>navigate('settings');document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeAuth();$('#tutor-modal')?.remove();$('#sidebar').classList.remove('open');$('#sidebar-scrim').classList.add('hidden');}});bindPageButtons();try{const r=await api('/api/auth/me');showApp(r.user);const p=await api('/api/profile');applyAccessibility(p.profile.accessibility);}catch{showPublic();}}
document.addEventListener('DOMContentLoaded',boot);
})();
